const mk=a=>new RegExp('^'+a.split(/(\{\}|\{#\}|\{\$\})/).map(p=>p==='{}'?'(.+?)':p==='{#}'?'(\\d+)':p==='{$}'?'([\\d\\s\\u00a0\\u202f.,]+\\s*درهم)':p.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('')+'$');
const trCore=k=>{
 if(LANG==='ar')return k;
 const D=I18N[LANG];
 if(PCL!==LANG){PC=D.p.map(([a,b])=>[mk(a),b]);PCL=LANG}
 let r=D.d[k];
 if(r===undefined){r=k;for(const [re,o] of PC){const x=re.exec(k);if(x){r=o.replace(/\{(\d)\}/g,(_,i)=>trCore((x[i]||'').trim()));break}}}
 return r.replace(/(\d[\s  ]*)درهم/g,'$1'+CUR[LANG]).replace(/←/g,'→');
};
const tr=s=>{if(LANG==='ar'||typeof s!=='string')return s;const m=/^(\s*)([\s\S]*?)(\s*)$/.exec(s);return m[2]?m[1]+trCore(m[2])+m[3]:s};
const trDom=root=>{if(LANG==='ar'||!root)return;
 const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),L=[];while(w.nextNode())L.push(w.currentNode);
 L.forEach(n=>{const v=n.nodeValue;if(AR.test(v)||v.indexOf('←')>-1){const t=tr(v);if(t!==v)n.nodeValue=t}});
 root.querySelectorAll('[placeholder],[aria-label],[alt],[title]').forEach(el=>['placeholder','aria-label','alt','title'].forEach(a=>{const v=el.getAttribute(a);if(v&&AR.test(v)){const t=tr(v);if(t!==v)el.setAttribute(a,t)}}))};
